import itertools
people = ['Alex', 'Ben', 'Chris', 'Dan', 'Eva']
opts = {'Eva': 'A', 'Chris': 'B', 'Ben': 'C', 'Dan': 'D'}
solutions = []
for p in itertools.permutations(people):
    m = {p[i]: i+1 for i in range(5)}
    cond1 = m['Chris'] % 2 == 0
    cond2 = m['Alex'] < m['Chris']
    cond3 = abs(m['Dan'] - m['Eva']) == 1
    cond4 = m['Ben'] not in [1, 5]
    cond5 = abs(m['Alex'] - m['Eva']) == 3
    if cond1 and cond2 and cond3 and cond4 and cond5:
        solutions.append(m)
answers = {opts[next(k for k, v in s.items() if v == 4)] for s in solutions}
answer = next(iter(answers))

